-- Archive knowledge schema. Generated by go run ./cmd/knowledge-schema.
CREATE TABLE IF NOT EXISTS `knowledge_document_version` (`id` bigint AUTO_INCREMENT,`source_version_id` bigint NOT NULL,`document_id` bigint NOT NULL,`archive_id` bigint NOT NULL,`title` varchar(255),`sequence` bigint,`state` varchar(32),`markdown` LONGTEXT,`summary` LONGTEXT,`summary_state` varchar(32),`digest` varchar(64),`error` varchar(500),`attempts` bigint,`lease` varchar(64),`lease_until` bigint,`next_run` bigint,`updated_at` bigint,PRIMARY KEY (`id`),INDEX `idx_knowledge_document_version_document_id` (`document_id`),INDEX `idx_knowledge_document_version_archive_id` (`archive_id`),INDEX `idx_knowledge_document_version_state` (`state`),CONSTRAINT `uni_knowledge_document_version_source_version_id` UNIQUE (`source_version_id`));
CREATE TABLE IF NOT EXISTS `knowledge_document_section` (`id` bigint AUTO_INCREMENT,`version_id` bigint NOT NULL,`position` bigint,`heading` varchar(255),`body` LONGTEXT,PRIMARY KEY (`id`),INDEX `idx_knowledge_document_section_version_id` (`version_id`));
CREATE TABLE IF NOT EXISTS `knowledge_document_workbook` (`version_id` bigint,`data` LONGTEXT,PRIMARY KEY (`version_id`));
